-- 001_companies_email.sql
-- Adds the email column to companies.
--
-- Why: company-signup.html uses the work email purely as a Supabase auth
-- credential. It lands in auth.users and was never copied to companies, so
-- there was no address on the row for Stripe or the booking emails to use.
--
-- Run once in the Supabase SQL editor. Already applied to production.
-- Do not edit this file after it has been run against a live database;
-- add a new numbered file instead.

alter table companies add column email text;
